  write(dir,files,"android/graphics/Path.java","package android.graphics;public class Path{public enum Direction{CW,CCW}public void addRoundRect(float l,float t,float r,float b,float rx,float ry,Direction d){path.append(new java.awt.geom.RoundRectangle2D.Float(l,t,r-l,b-t,rx*2,ry*2),false);}java.awt.geom.Path2D.Float path=new java.awt.geom.Path2D.Float();public void moveTo(float x,float y){path.moveTo(x,y);}public void lineTo(float x,float y){path.lineTo(x,y);}public void close(){path.closePath();}}");
  write(dir,files,"android/graphics/Paint.java","package android.graphics;public class Paint{public enum Style{FILL,STROKE}public enum Align{LEFT,CENTER,RIGHT}int color,alpha=255;float size=12;boolean bold;public Paint(int n){}public void setStyle(Style s){}public void setColor(int c){color=c;}public void setAlpha(int a){alpha=a;}public void setColorFilter(ColorFilter f){}public void setTextSize(float n){size=n;}public void setTextAlign(Align a){}public void setTypeface(Typeface t){bold=t.bold;}java.awt.Font font(){return new java.awt.Font(\"Microsoft YaHei\",bold?1:0,12).deriveFont(Math.max(.1f,size));}public float measureText(String text){return (float)font().getStringBounds(text,new java.awt.font.FontRenderContext(null,true,true)).getWidth();}}");
  write(dir,files,"android/graphics/Canvas.java","package android.graphics;import java.awt.*;import java.awt.geom.*;import java.awt.image.*;import java.util.*;public class Canvas{public final BufferedImage image;public final java.util.List<String> texts=new ArrayList<>();Graphics2D g;Deque<AffineTransform> stack=new ArrayDeque<>();public Canvas(int w,int h){image=new BufferedImage(w,h,2);g=image.createGraphics();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);}void paint(Paint p){g.setColor(new Color((p.color&0xffffff)|(p.alpha<<24),true));g.setFont(p.font());}public void save(){stack.push(g.getTransform());}public void restore(){g.setTransform(stack.pop());g.setClip(null);}public void translate(float x,float y){g.translate(x,y);}public void clipRect(float l,float t,float r,float b){g.clip(new Rectangle2D.Float(l,t,r-l,b-t));}public void clipPath(Path p){g.clip(p.path);}public void drawRect(float l,float t,float r,float b,Paint p){paint(p);g.fill(new Rectangle2D.Float(l,t,r-l,b-t));}public void drawPath(Path path,Paint p){paint(p);g.fill(path.path);}public void drawText(String text,float x,float y,Paint p){paint(p);texts.add(text);g.drawString(text,x,y);}}");
